DO $patch$ DECLARE ns text; f text; BEGIN FOR ns IN SELECT unnest(ARRAY['buildwatch','buildwatch_audit']) LOOP SELECT pg_get_functiondef(to_regprocedure(ns||'.bw_research_api(jsonb,text,text,jsonb,jsonb)')) INTO f; f=replace(f,'(SELECT to_jsonb(a) FROM approval_policy a WHERE project_id=row.project_id) IS DISTINCT FROM value->''policy''','coalesce((SELECT to_jsonb(a) FROM approval_policy a WHERE project_id=row.project_id),''null''::jsonb) IS DISTINCT FROM value->''policy'''); EXECUTE f; END LOOP; END $patch$;
